PAGES = []


def page(section, title, url, route, models, service, html, functionality, interaction, **extra):
    PAGES.append(dict(section=section, title=title, url=url, route=route, models=models,
                      service=service, html=html, functionality=functionality,
                      interaction=interaction, **extra))


